-- Minimal production-shaped dependencies, ONLY in a new empty test database.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE aif_locations(id uuid PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,is_active boolean NOT NULL DEFAULT true);
CREATE TABLE aif_brands(id uuid PRIMARY KEY,name text);
CREATE TABLE aif_categories(id uuid PRIMARY KEY,name_ro text);
CREATE TABLE aif_product_models(id uuid PRIMARY KEY,title_ro text,model_code text,brand_id uuid REFERENCES aif_brands(id),category_id uuid REFERENCES aif_categories(id));
CREATE TABLE aif_product_variants(id uuid PRIMARY KEY,model_id uuid REFERENCES aif_product_models(id),barcode text,internal_sku text,size text,color_name text,image_url text,sell_price numeric(14,2),buy_price numeric(14,2));
CREATE TABLE aif_stock(location_id uuid REFERENCES aif_locations(id),variant_id uuid REFERENCES aif_product_variants(id),qty integer NOT NULL CHECK(qty>=0),reserved_qty integer NOT NULL DEFAULT 0 CHECK(reserved_qty>=0 AND reserved_qty<=qty),updated_at timestamptz DEFAULT now(),PRIMARY KEY(location_id,variant_id));
CREATE TABLE aif_stock_retail_book(location_id uuid REFERENCES aif_locations(id),variant_id uuid REFERENCES aif_product_variants(id),qty numeric(18,3) NOT NULL,book_value numeric(18,2) NOT NULL,seeded boolean DEFAULT false,updated_at timestamptz DEFAULT now(),PRIMARY KEY(location_id,variant_id));
CREATE TABLE aif_stock_transfer_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transfer_id text UNIQUE NOT NULL,document_number text UNIQUE NOT NULL,series text,sequence_number bigint,sequence_year integer,title text,subtitle text,note text,status text NOT NULL DEFAULT 'issued',actor text,owner_key text,line_count integer,total_qty integer,from_location_summary text,to_location_summary text,raw jsonb NOT NULL DEFAULT '{}',document_type text,source_location_id text,target_location_id text,external_reference text,reason_code text,reason_text text,operation_direction text,price_basis text,total_value numeric(18,2),currency_code text,document_date date,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE aif_stock_transfer_document_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES aif_stock_transfer_documents(id),line_no integer NOT NULL,variant_id text,product_title text,brand_name text,category_name text,product_code text,barcode text,color_name text,size text,image_url text,from_location_id text,from_location_name text,to_location_id text,to_location_name text,qty integer NOT NULL CHECK(qty>0),source_before integer,source_after integer,target_before integer,target_after integer,unit_price numeric(18,2),line_total numeric(18,2),currency_code text,price_basis text,qty_delta integer,raw jsonb NOT NULL DEFAULT '{}',UNIQUE(document_id,line_no));
CREATE TABLE aif_stock_movements(id bigserial PRIMARY KEY,movement_type text,source_type text,source_id varchar(40),location_id uuid REFERENCES aif_locations(id),variant_id uuid REFERENCES aif_product_variants(id),qty_delta integer,qty_before integer,qty_after integer,actor text,raw jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
